<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { createResource } from 'frappe-ui'
import {
	statusPillClass,
	umurPillClass,
	umurLabel,
	docstatusLabel,
	docstatusPillClass,
} from '../data/motorTarikanStatus'
import { refreshCsrfToken } from '../data/session'
import { currentUser, loadMyRoles } from '../data/user'
import { notifyError, notifyInfo, notifySuccess } from '../composables/toast'
import SelectMenu from '../components/SelectMenu.vue'

const DOCTYPE = 'Motor Tarikan'
const route = useRoute()
const router = useRouter()
const name = computed(() => route.params.name)

// Mode entri DRAFT (belum tersimpan, edit mode, Save = insert), dua varian:
//  - Amend  : route 'MotorTarikanAmend'  (/motor-tarikan/amend/:from) — salinan dari
//             dokumen Cancelled (frappe.copy_doc).
//  - New    : route 'MotorTarikanCreate' (/motor-tarikan/new) — form baru dari default.
// Keduanya berbagi perilaku: editMode dipaksa, canEdit true, tidak fetch dokumen,
// Save meng-insert dokumen baru. Persis desk: Draft dibuat saat Save.
const isAmend = computed(() => route.name === 'MotorTarikanAmend')
const isNew = computed(() => route.name === 'MotorTarikanCreate')
const isDraftEntry = computed(() => isAmend.value || isNew.value)
const amendFrom = computed(() => (isAmend.value ? String(route.params.from || '') : ''))
const amendReady = ref(false)

const displayTitle = computed(() => {
	if (isNew.value) return 'Tambah Motor Tarikan'
	if (isAmend.value) return `Amendment dari ${amendFrom.value}`
	return doc.data?.name || name.value
})
const displayStatusUnit = computed(() =>
	isDraftEntry.value ? form.status_unit : doc.data?.status_unit
)
const displayUmur = computed(() => (isDraftEntry.value ? form.umur_stok : doc.data?.umur_stok))
const pageLoading = computed(() => (isDraftEntry.value ? !amendReady.value : doc.loading))

// Kolom child table (read-only). Diketahui dari doctype masing-masing.
const CHILD_COLUMNS = {
	penawaran_harga: [
		{ key: 'tanggal_penawaran', label: 'Tanggal', type: 'Date' },
		{ key: 'nama_penawar', label: 'Penawar' },
		{ key: 'nominal_penawaran', label: 'Nominal', type: 'Currency' },
	],
	riwayat_posisi: [
		{ key: 'tanggal_perpindahan', label: 'Tanggal', type: 'Date' },
		{ key: 'posisi_asal', label: 'Dari' },
		{ key: 'posisi_tujuan', label: 'Ke' },
		{ key: 'dokumen_perpindahan', label: 'Dokumen' },
	],
}
function childColumns(fieldname) {
	return CHILD_COLUMNS[fieldname] || []
}
// Baris child table: dari draft (form) saat amend, dari dokumen saat baca biasa.
function tableRows(fieldname) {
	const src = isDraftEntry.value ? form[fieldname] : doc.data?.[fieldname]
	return Array.isArray(src) ? src : []
}
function childCell(col, val) {
	if (val == null || val === '') return '—'
	if (col.type === 'Currency') return currencyDisplay(val)
	if (col.type === 'Date') return formatDateDisplay(val)
	return String(val)
}

// Textarea auto-tinggi.
const AUTOGROW_MAX = 180
function fitTextarea(el) {
	if (!el) return
	el.style.height = 'auto'
	const h = Math.min(Math.max(el.scrollHeight, 44), AUTOGROW_MAX)
	el.style.height = `${h}px`
	el.style.overflowY = el.scrollHeight > AUTOGROW_MAX ? 'auto' : 'hidden'
}
const vAutogrow = {
	mounted(el) {
		el.addEventListener('input', () => fitTextarea(el))
		nextTick(() => fitTextarea(el))
	},
	updated(el) {
		nextTick(() => fitTextarea(el))
	},
}

// ---- Fetch dokumen ---------------------------------------------------------
const doc = createResource({
	url: 'frappe.client.get',
	makeParams() {
		return { doctype: DOCTYPE, name: name.value }
	},
	auto: false,
	onSuccess() {
		syncFormFromDoc()
	},
})

// ---- Meta doctype ----------------------------------------------------------
const metaFields = ref([])
const SKIP_TYPES = [
	'Section Break',
	'Column Break',
	'Tab Break',
	'HTML',
	'Button',
	'Heading',
	'Fold',
	'Barcode',
]
// Sembunyikan section Audit + field housekeeping (selaras tampilan desk).
const SKIP_FIELDS = ['audit_section', 'amended_from']

function isTextarea(ft) {
	return ['Small Text', 'Text', 'Long Text', 'Code', 'Text Editor'].includes(ft)
}
function isNumberField(ft) {
	return ['Int', 'Float', 'Currency', 'Percent'].includes(ft)
}
function selectOptions(field) {
	return String(field.options || '')
		.split('\n')
		.map((s) => s.trim())
		.filter(Boolean)
}

// ---- Editabilitas ----------------------------------------------------------
// Motor Tarikan TIDAK punya workflow. Submittable → editable HANYA saat docstatus 0
// dan user punya izin tulis (permlevel 0). Audiens portal (Manager Finance / Director
// / Staff Finance) read-only → tombol Edit tidak muncul; hanya penulis (mis. System
// Manager) yang bisa mengedit.
const editMode = ref(false)
const wfStateField = ref(null)
const wfEditStates = ref({})
const wfLoaded = ref(false)
async function loadWorkflowEditMap() {
	try {
		const params = new URLSearchParams({ doctype: DOCTYPE })
		const res = await fetch(
			`/api/method/juragan.api.portal.meta.get_workflow_edit_map?${params.toString()}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		if (res.ok) {
			const msg = (await res.json()).message || {}
			wfStateField.value = msg.state_field || null
			wfEditStates.value = msg.states || {}
		}
	} catch (e) {
		/* fallback */
	} finally {
		wfLoaded.value = true
	}
}

const readablePermlevels = ref(new Set([0]))
const writablePermlevels = ref(new Set([0]))
const permLoaded = ref(false)
async function loadPermlevelAccess() {
	try {
		const params = new URLSearchParams({ doctype: DOCTYPE })
		const res = await fetch(
			`/api/method/juragan.api.portal.meta.get_permlevel_access?${params.toString()}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		if (res.ok) {
			const msg = (await res.json()).message || {}
			readablePermlevels.value = new Set(msg.read || [0])
			writablePermlevels.value = new Set(msg.write || [])
		}
	} catch (e) {
		writablePermlevels.value = new Set()
	} finally {
		permLoaded.value = true
	}
}

const canEditDoc = computed(() => {
	// Mode entri draft (New/Amend) = belum tersimpan → selalu editable.
	if (isDraftEntry.value) return true
	if (!wfLoaded.value || !permLoaded.value || !currentUser.rolesLoaded) return false
	if (doc.data?.docstatus !== 0) return false
	if (wfStateField.value) {
		const status = doc.data?.[wfStateField.value]
		if (!status) return true
		const allow = wfEditStates.value[status] || []
		return (currentUser.roles || []).some((r) => allow.includes(r))
	}
	// Tanpa workflow → butuh izin tulis permlevel 0.
	return writablePermlevels.value.has(0)
})

function enterEditMode() {
	if (canEditDoc.value) editMode.value = true
}
function cancelEdit() {
	// Batal saat New → kembali ke list; saat Amend → kembali ke dokumen sumber.
	if (isNew.value) {
		router.replace({ name: 'MotorTarikan' })
		return
	}
	if (isAmend.value) {
		router.replace({ name: 'MotorTarikanDetail', params: { name: amendFrom.value } })
		return
	}
	syncFormFromDoc()
	editMode.value = false
	openDropdown.value = ''
	saveError.value = ''
}
watch(canEditDoc, (can) => {
	if (!can) editMode.value = false
})

// ---- Form editable ---------------------------------------------------------
const form = reactive({})
const saving = ref(false)
const saveError = ref('')

function loadForm(src) {
	Object.assign(form, src || {})
	for (const f of metaFields.value) {
		if (f.fieldtype === 'Link' && form[f.fieldname] != null && form[f.fieldname] !== '') {
			form[f.fieldname] = String(form[f.fieldname])
		}
	}
	resolveAllLinks()
}
function syncFormFromDoc() {
	if (isDraftEntry.value) return
	loadForm(doc.data)
}

const inputClass =
	'min-h-[44px] w-full rounded-md border border-ui-line-gray-300 bg-ui-surface px-3 py-2 text-base text-ui-ink-gray-800 outline-none transition focus:border-primary focus:ring-2 focus:ring-inset focus:ring-primary/30 md:min-h-0'

// ---- Kondisi depends_on / read_only / reqd ---------------------------------
function evalCondition(expr) {
	if (!expr) return true
	try {
		const code = String(expr).replace(/^eval:/, '')
		const in_list = (list, item) => Array.isArray(list) && list.includes(item)
		const cint = (v) => parseInt(v, 10) || 0
		const cstr = (v) => (v == null ? '' : String(v))
		const flt = (v) => parseFloat(v) || 0
		// eslint-disable-next-line no-new-func
		return !!new Function('doc', 'in_list', 'cint', 'cstr', 'flt', `return (${code})`)(
			form,
			in_list,
			cint,
			cstr,
			flt
		)
	} catch (e) {
		return true
	}
}
function isFieldReqd(field) {
	if (field.reqd) return true
	return field.mandatory_depends_on ? evalCondition(field.mandatory_depends_on) : false
}
function isFieldReadOnly(field) {
	if (!editMode.value) return true
	if (field.read_only) return true
	if (!writablePermlevels.value.has(field.permlevel || 0)) return true
	return field.read_only_depends_on ? evalCondition(field.read_only_depends_on) : false
}
function fieldClass(field) {
	return [
		inputClass,
		isFieldReadOnly(field)
			? '!bg-ui-surface-gray-100 !text-ui-ink-gray-500 !border-ui-line-gray-200 cursor-not-allowed'
			: '',
	]
}

// ---- Format nilai ----------------------------------------------------------
function formatCurrency(v) {
	const n = Number(v)
	if (v === '' || v == null || Number.isNaN(n)) return String(v ?? '')
	return new Intl.NumberFormat('id-ID', {
		minimumFractionDigits: 2,
		maximumFractionDigits: 2,
	}).format(n)
}
function currencyDisplay(v) {
	if (v === '' || v == null || Number.isNaN(Number(v))) return ''
	return `Rp ${formatCurrency(v)}`
}
function numberDisplay(field, v) {
	if (v == null || v === '') return '—'
	if (field.fieldtype === 'Currency') return currencyDisplay(v) || '—'
	const n = Number(v)
	if (Number.isNaN(n)) return String(v)
	return new Intl.NumberFormat('id-ID').format(n)
}
