// ---- Link searchable + resolusi judul --------------------------------------
const linkTitleField = reactive({})
const linkTitles = reactive({})
const linkOptions = reactive({})

async function loadLinkMeta() {
	const dts = new Set()
	for (const f of metaFields.value) {
		if (f.fieldtype === 'Link' && f.options) dts.add(f.options)
	}
	await Promise.all(
		[...dts].map(async (dt) => {
			try {
				const res = await fetch(
					`/api/method/frappe.desk.form.load.getdoctype?doctype=${encodeURIComponent(
						dt
					)}`,
					{
						method: 'GET',
						credentials: 'include',
						headers: { Accept: 'application/json' },
					}
				)
				const json = await res.json()
				const docs = json.docs || json.message?.docs || []
				const meta = docs.find((x) => x.name === dt) || docs[0]
				linkTitleField[dt] = (meta && meta.title_field) || null
			} catch (e) {
				linkTitleField[dt] = null
			}
		})
	)
	resolveAllLinks()
	for (const dt of dts) loadLinkOptions(dt)
}
async function loadLinkOptions(dt) {
	if (linkOptions[dt]) return
	const titleField = linkTitleField[dt]
	try {
		const flds = titleField ? ['name', titleField] : ['name']
		const lparams = new URLSearchParams({
			doctype: dt,
			fields: JSON.stringify(flds),
			limit_page_length: '101',
			order_by: 'name asc',
		})
		const lres = await fetch(`/api/method/frappe.client.get_list?${lparams.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const ljson = await lres.json()
		const recs = ljson.message || []
		if (recs.length && recs.length <= 100) {
			linkOptions[dt] = recs.map((r) => ({
				value: String(r.name),
				label: (titleField && r[titleField]) || String(r.name),
			}))
		}
	} catch (e) {
		/* abaikan */
	}
}
async function resolveLinkTitle(dt, value) {
	const key = `${dt}:${value}`
	if (value == null || value === '' || linkTitles[key] !== undefined) return
	const titleField = linkTitleField[dt]
	if (titleField === undefined) return
	if (titleField === null) {
		linkTitles[key] = String(value)
		return
	}
	try {
		const params = new URLSearchParams({
			doctype: dt,
			fieldname: titleField,
			filters: String(value),
		})
		const res = await fetch(`/api/method/frappe.client.get_value?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const json = await res.json()
		const msg = json.message
		const title = msg && typeof msg === 'object' ? msg[titleField] : msg
		linkTitles[key] = title != null && title !== '' ? title : String(value)
	} catch (e) {
		linkTitles[key] = String(value)
	}
}
function resolveAllLinks() {
	for (const f of metaFields.value) {
		if (f.fieldtype === 'Link' && f.options && form[f.fieldname]) {
			resolveLinkTitle(f.options, form[f.fieldname])
		}
	}
}
// BSTK dipilih dari daftar yang disusun server (kelayakannya tidak bisa
// dinyatakan sebagai filter biasa), jadi cache daftar penuh per-doctype —
// yang dipakai untuk link kecil — tidak boleh menggantikannya.
const SERVER_PICKER_FIELDS = ['bstk_ref']
function cachedLinkOptions(field) {
	if (SERVER_PICKER_FIELDS.includes(field.fieldname)) return null
	return linkFilters(field).length ? null : linkOptions[field.options]
}
function linkDisplay(field) {
	const v = form[field.fieldname]
	if (!v) return ''
	const opts = linkOptions[field.options]
	if (opts) {
		const cur = opts.find((o) => String(o.value).toLowerCase() === String(v).toLowerCase())
		if (cur) return cur.label
	}
	const t = linkTitles[`${field.options}:${v}`]
	if (t !== undefined) return t
	if (linkTitleField[field.options] === null) return v
	return '…'
}

const openDropdown = ref('')
const linkSearch = ref('')
const linkResults = ref([])
const linkSearchLoading = ref(false)
function optionMatch(opt, field) {
	const v = form[field.fieldname]
	if (v == null || v === '') return false
	return String(opt.value).toLowerCase() === String(v).toLowerCase()
}
function linkFilters(field) {
	let raw = field.link_filters
	if (!raw) return []
	try {
		if (typeof raw === 'string') raw = JSON.parse(raw)
	} catch (e) {
		return []
	}
	const out = []
	const push = (f, op, v) => {
		if (typeof v === 'string' && /^eval:|^doc\./.test(v)) return
		out.push([f, op, v])
	}
	if (Array.isArray(raw)) {
		for (const c of raw) {
			if (!Array.isArray(c)) continue
			if (c.length === 4) push(c[1], c[2], c[3])
			else if (c.length === 3) push(c[0], c[1], c[2])
		}
	} else if (raw && typeof raw === 'object') {
		for (const [k, v] of Object.entries(raw)) push(k, '=', v)
	}
	return out
}
function toggleLinkDropdown(field) {
	if (openDropdown.value === field.fieldname) {
		openDropdown.value = ''
		return
	}
	openDropdown.value = field.fieldname
	linkSearch.value = ''
	const opts = cachedLinkOptions(field)
	if (opts) linkResults.value = opts
	else fetchLinkResults(field, '')
}
async function fetchLinkResults(field, query) {
	const dt = field.options
	const titleField = linkTitleField[dt]
	linkSearchLoading.value = true
	linkResults.value = []
	try {
		const flds = titleField ? ['name', titleField] : ['name']
		// BSTK punya syarat kelayakan yang tidak bisa dinyatakan sebagai filter
		// biasa (belum dipakai Motor Tarikan lain), jadi daftarnya diambil dari
		// server — sumber kelayakan yang sama dengan picker desk.
		if (field.fieldname === 'bstk_ref') {
			if (!form.no_perjanjian) {
				notifyInfo('Pilih No Perjanjian dulu untuk melihat BSTK yang tersedia.')
				return
			}
			// catch sendiri: catch generik di bawah hanya mengosongkan daftar,
			// dan daftar kosong tanpa sebab menyesatkan di sini.
			try {
				const rows =
					(await panggilMetode(
						'juragan.ops.hooks.motor_tarikan.get_available_bstk_options',
						{
							no_perjanjian: String(form.no_perjanjian),
							txt: query || '',
							current_motor_tarikan: isNew.value ? '' : String(name.value || ''),
						}
					)) || []
				linkResults.value = rows.map((r) => ({
					value: String(r.name),
					label: r.nama_nasabah ? `${r.name} — ${r.nama_nasabah}` : String(r.name),
				}))
			} catch (e) {
				notifyError(e, 'Gagal memuat daftar BSTK')
			}
			return
		}

		const params = new URLSearchParams({
			doctype: dt,
			fields: JSON.stringify(flds),
			limit_page_length: '20',
			order_by: 'name asc',
		})
		const lf = linkFilters(field)
		if (lf.length) params.set('filters', JSON.stringify(lf))
		if (query) {
			const ors = [['name', 'like', `%${query}%`]]
			if (titleField) ors.push([titleField, 'like', `%${query}%`])
			params.set('or_filters', JSON.stringify(ors))
		}
		const res = await fetch(`/api/method/frappe.client.get_list?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const json = await res.json()
		const recs = json.message || []
		linkResults.value = recs.map((r) => ({
			value: String(r.name),
			label: (titleField && r[titleField]) || String(r.name),
		}))
	} catch (e) {
		linkResults.value = []
	} finally {
		linkSearchLoading.value = false
	}
}
let linkSearchTimer = null
function onLinkSearch(field) {
	const q = linkSearch.value.trim()
	const opts = cachedLinkOptions(field)
	if (opts) {
		const ql = q.toLowerCase()
		linkResults.value = ql
			? opts.filter(
					(o) =>
						o.label.toLowerCase().includes(ql) ||
						String(o.value).toLowerCase().includes(ql)
			  )
			: opts
		return
	}
	clearTimeout(linkSearchTimer)
	linkSearchTimer = setTimeout(() => fetchLinkResults(field, q), 300)
}
function selectLink(field, value, label) {
	form[field.fieldname] = value
	if (label != null) linkTitles[`${field.options}:${value}`] = label
	openDropdown.value = ''
	applyFetchFrom(field, value)

	// Serah terima BSTK — cerminan motor_tarikan_bstk_autofill.js di desk.
	if (field.fieldname === 'no_perjanjian') autoisiBstkDariKontrak(value)
	else if (field.fieldname === 'bstk_ref') autoisiDariBstkTerpilih(value)
}

// ---- Auto-isi data serah terima BSTK ---------------------------------------
// Aturannya sama persis dengan desk, dan sengaja memakai method server yang
// sama supaya tidak ada logika kembar: kontrak dengan TEPAT SATU BSTK layak
// mengisi sendiri; lebih dari satu tidak ditebak — user memilih dari picker,
// dan pilihan itu mengisi field yang sama.
const PIC_DOCTYPE_BY_EKSEKUSI = { INTERNAL: 'Mapping Collector', EKSTERNAL: 'PIC Tarikan' }

async function panggilMetode(metode, args) {
	const params = new URLSearchParams(args)
	const res = await fetch(`/api/method/${metode}?${params.toString()}`, {
		method: 'GET',
		credentials: 'include',
		headers: { Accept: 'application/json' },
	})
	const json = await res.json().catch(() => ({}))
	// Kegagalan TIDAK ditelan diam-diam: auto-isi yang gagal tanpa jejak tidak
	// bisa dibedakan dari "kontraknya memang tidak punya BSTK".
	if (!res.ok) throw new Error(json?.exception || json?.message || `HTTP ${res.status}`)
	return json?.message ?? null
}

async function autoisiBstkDariKontrak(no_perjanjian) {
	if (!no_perjanjian || form.tipe_motor === 'Titipan') return
	try {
		const res = await panggilMetode(
			'juragan.ops.hooks.motor_tarikan.get_bstk_for_no_perjanjian',
			{ no_perjanjian, current_motor_tarikan: isNew.value ? '' : String(name.value || '') }
		)
		if (!res) return
		if (res.count > 1) {
			notifyInfo(
				`Ada ${res.count} BSTK untuk No Perjanjian ini — pilih BSTK-nya sendiri.`
			)
			return
		}
		if (res.count !== 1) return
		// Eksekusi & PIC sengaja tidak ikut pada jalur otomatis; server tetap
		// menetapkannya dari Eksekutor BSTK saat disimpan.
		isiDariBstk(res.bstk, { dengan_eksekusi: false })
	} catch (e) {
		notifyError(e, 'Gagal mengambil data BSTK dari No Perjanjian')
	}
}

async function autoisiDariBstkTerpilih(nomor_bstk) {
	if (!nomor_bstk) return
	try {
		const bstk = await panggilMetode(
			'juragan.ops.hooks.motor_tarikan.get_bstk_serah_terima',
			{ nomor_bstk }
		)
		if (bstk) isiDariBstk(bstk)
	} catch (e) {
		notifyError(e, 'Gagal mengambil data serah terima BSTK')
	}
}

// Melepas isian sebuah field Link. Untuk bstk_ref sekaligus membersihkan data
// serah terima yang tadi ikut terisi — kebalikan isiDariBstk(), dan cerminan
// _clear_bstk_derived_fields() di ops/hooks/motor_tarikan.py yang melakukan hal
// sama saat disimpan. Tanpa ini unit menyimpan kelengkapan milik BSTK yang sudah
// dilepas, dan BSTK-nya sendiri tidak pernah bisa di-Cancel.
function kosongkanLink(field) {
	form[field.fieldname] = ''
	openDropdown.value = ''
	applyFetchFrom(field, '')
	if (field.fieldname === 'bstk_ref') kosongkanDataBstk()
}

function kosongkanDataBstk() {
	form.tanggal_bstk = null
	form.has_kunci = 0
	form.has_stnk = 0
	form.keterangan_stnk = ''
	form.tanggal_janji_tebus = null
	form.eksekusi = ''
	form.nama_pic_tarik_doctype = null
	form.nama_pic_tarik = ''
}

function isiDariBstk(bstk, { dengan_eksekusi = true } = {}) {
	form.bstk_ref = bstk.name
	linkTitles[`BSTK:${bstk.name}`] = bstk.name
	form.no_bstk = ''
	form.tanggal_bstk = bstk.tanggal_bstk || null
	form.has_kunci = bstk.kunci ? 1 : 0
	form.has_stnk = bstk.stnk ? 1 : 0
	form.keterangan_stnk = bstk.keterangan_stnk || ''
	// Server sudah mengosongkannya bila kategori BSTK bukan "Janji Tebus".
	form.tanggal_janji_tebus = bstk.tanggal_janji_tebus || null
	if (!dengan_eksekusi) return
	form.eksekusi = bstk.eksekusi
	form.nama_pic_tarik_doctype = PIC_DOCTYPE_BY_EKSEKUSI[bstk.eksekusi] || null
