}

// Tiru `fetch_from` Frappe: saat sebuah Link berubah, isi field turunannya dari
// dokumen tertaut TANPA save (mis. no_perjanjian → nama_nasabah/cabang/nopol/…).
async function applyFetchFrom(linkField, value) {
	const prefix = `${linkField.fieldname}.`
	const targets = metaFields.value.filter(
		(f) => typeof f.fetch_from === 'string' && f.fetch_from.startsWith(prefix)
	)
	if (!targets.length) return
	if (!value) {
		for (const t of targets) form[t.fieldname] = null
		return
	}
	const sourceFields = targets.map((t) => t.fetch_from.slice(prefix.length))
	try {
		const params = new URLSearchParams({
			doctype: linkField.options,
			filters: JSON.stringify({ name: value }),
			fieldname: JSON.stringify(sourceFields),
		})
		const res = await fetch(`/api/method/frappe.client.get_value?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		if (!res.ok) return
		const data = (await res.json())?.message || {}
		for (const t of targets) {
			const src = t.fetch_from.slice(prefix.length)
			if (src in data) form[t.fieldname] = data[src]
		}
	} catch (e) {
		/* abaikan — server tetap mengisi fetch_from saat save */
	}
}

// ---- Susun section dari meta -----------------------------------------------
// Tab pertama di Frappe tidak punya Tab Break sendiri — field sebelum Tab Break
// pertama masuk tab bawaan berlabel "Details", persis seperti form desk.
const TAB_UTAMA = { key: '__details__', label: 'Details' }

const sectionsStructure = computed(() => {
	const sections = []
	let curTab = TAB_UTAMA
	let curSection = null
	let curCol = null
	const ensureSection = () => {
		if (!curSection) {
			curCol = []
			curSection = { label: '', tab: curTab.key, columns: [curCol] }
			sections.push(curSection)
		}
	}
	for (const f of metaFields.value) {
		const ft = f.fieldtype
		if (ft === 'Tab Break') {
			curTab = { key: f.fieldname, label: f.label || f.fieldname }
			curSection = null
			curCol = null
			continue
		}
		if (ft === 'Section Break') {
			curCol = []
			curSection = { label: f.label || '', tab: curTab.key, columns: [curCol] }
			sections.push(curSection)
			continue
		}
		if (ft === 'Column Break') {
			if (!curSection) ensureSection()
			else {
				curCol = []
				curSection.columns.push(curCol)
			}
			continue
		}
		if (SKIP_TYPES.includes(ft) || SKIP_FIELDS.includes(f.fieldname)) continue
		ensureSection()
		curCol.push(f)
	}
	return sections
})

// Urutan tab diambil dari meta, jadi tidak bisa melenceng dari desk.
const tabsStructure = computed(() => {
	const tabs = [TAB_UTAMA]
	for (const f of metaFields.value) {
		if (f.fieldtype === 'Tab Break' && !f.hidden) {
			tabs.push({ key: f.fieldname, label: f.label || f.fieldname })
		}
	}
	return tabs
})

const MOKAS_TAB = 'mokas_bengkel_tab'

// Berbeda dari desk yang menyembunyikan tab "Mokas & Bengkel" untuk unit yang
// posisinya tidak terdaftar di Pengaturan Dealer Bengkel: di portal tab itu
// SELALU tampil (permintaan user). Di site ini hanya satu posisi yang terdaftar
// (MARINA) sehingga aturan desk membuat tab-nya nyaris tidak pernah muncul —
// termasuk di form Tambah, saat Posisi Unit memang belum dipilih.
// eslint-disable-next-line no-unused-vars -- argumennya sengaja dipertahankan:
// di sinilah aturan per-tab dipasang kembali kalau nanti diperlukan.
function tabVisible(key) {
	return true
}

const activeTab = ref(TAB_UTAMA.key)

// Ikon per tab; kuncinya fieldname Tab Break dari meta. Tab tanpa ikon khusus
// memakai ikon dokumen yang sama dengan tab "Data" di Data Pengajuan.
const TAB_ICONS = {
	[MOKAS_TAB]:
		'<path d="M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.77-3.77a6 6 0 0 1-7.94 7.94l-6.91 6.91a2.12 2.12 0 0 1-3-3l6.91-6.91a6 6 0 0 1 7.94-7.94l-3.76 3.76z"/>',
}
const TAB_IKON_BAWAAN =
	'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18"/><path d="M9 21V9"/>'
function tabIcon(key) {
	return TAB_ICONS[key] || TAB_IKON_BAWAAN
}

// Bar tab menempel TEPAT di bawah header yang juga sticky; tanpa pengukuran
// ini keduanya akan tumpang tindih di top: 0. Sama seperti Data Pengajuan.
const headerRef = ref(null)
const tabStripRef = ref(null)
const tabTop = ref(0)
function measureSticky() {
	// Overlap 1px supaya tidak ada celah rambut akibat pembulatan sub-pixel.
	tabTop.value = Math.max(0, (headerRef.value?.offsetHeight || 0) - 1)
}
let _stickyRO = null
function setupStickyObservers() {
	if (typeof ResizeObserver === 'undefined') return
	_stickyRO = new ResizeObserver(() => measureSticky())
	if (headerRef.value) _stickyRO.observe(headerRef.value)
}

// Field terlihat: tidak hidden, permlevel boleh dibaca, depends_on terpenuhi.
function fieldVisible(f) {
	if (f.hidden) return false
	if (!readablePermlevels.value.has(f.permlevel || 0)) return false
	if (f.depends_on && !evalCondition(f.depends_on)) return false
	return true
}
function hasValue(f) {
	const v = doc.data?.[f.fieldname]
	if (f.fieldtype === 'Check') return !!v
	if (Array.isArray(v)) return v.length > 0
	return !(v == null || (typeof v === 'string' && v.trim() === ''))
}
function hasFormValue(f) {
	const v = form[f.fieldname]
	if (f.fieldtype === 'Check') return !!v
	if (Array.isArray(v)) return v.length > 0
	return !(v == null || (typeof v === 'string' && v.trim() === ''))
}

// Section yang dirender.
//  - Mode baca  → hanya field terlihat yang ADA ISINYA.
//  - Mode edit  → field yang BISA DITULIS user, atau read-only yang sudah ada isinya
//    (mis. hasil fetch_from). Field read-only kosong (dihitung server) disembunyikan
//    supaya form create tidak penuh field kosong.
const renderedSections = computed(() => {
	const out = []
	for (const sec of sectionsStructure.value) {
		if (!tabVisible(sec.tab)) continue
		const columns = sec.columns
			.map((col) =>
				col.filter((f) => {
					if (!fieldVisible(f)) return false
					if (f.fieldtype === 'Table') return tableRows(f.fieldname).length > 0
					if (editMode.value) return !isFieldReadOnly(f) || hasFormValue(f)
					return hasValue(f)
				})
			)
			.filter((col) => col.length)
		if (columns.length) out.push({ ...sec, columns })
	}
	return out
})

const sectionsTabAktif = computed(() =>
	renderedSections.value.filter((s) => s.tab === activeTab.value)
)

// Tab yang benar-benar ditampilkan: terlihat DAN punya isi.
//
// HARUS dideklarasikan sesudah `renderedSections`: `watch` di bawah membaca
// sumbernya sekali saat setup untuk merekam nilai awal, dan pembacaan itu
// menyentuh `renderedSections` — kalau blok ini di atasnya, const-nya masih di
// temporal dead zone dan komponen gagal dimuat.
const visibleTabs = computed(() =>
	tabsStructure.value.filter(
		(t) => tabVisible(t.key) && renderedSections.value.some((s) => s.tab === t.key)
	)
)
// Tab aktif bisa lenyap (posisi unit berubah, atau isinya habis tersaring) —
// jatuhkan ke tab pertama supaya kontennya tidak pernah kosong tanpa sebab.
watch(visibleTabs, (tabs) => {
	if (tabs.length && !tabs.some((t) => t.key === activeTab.value)) {
		activeTab.value = tabs[0].key
	}
})

// ---- Simpan ----------------------------------------------------------------
function frappeError(json) {
	try {
		if (json && json._server_messages) {
			const arr = JSON.parse(json._server_messages)
			return arr
				.map((m) => {
					try {
						return JSON.parse(m).message
					} catch (e) {
						return m
					}
				})
				.join('\n')
		}
	} catch (e) {
		/* ignore */
	}
	return (json && (json.exception || json.message)) || ''
}
async function saveDoc(docObj) {
	const res = await fetch('/api/method/frappe.client.save', {
		method: 'POST',
		credentials: 'include',
		headers: {
			'Content-Type': 'application/json',
			Accept: 'application/json',
			'X-Frappe-CSRF-Token': window.csrf_token || '',
		},
		body: JSON.stringify({ doc: docObj }),
	})
	const json = await res.json().catch(() => ({}))
	if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
	return json.message
}
async function saveDocument() {
	saving.value = true
	saveError.value = ''
	try {
		const payload = JSON.parse(JSON.stringify(form))
		payload.doctype = DOCTYPE
		if (isDraftEntry.value) {
			// New/Amend: draft baru → INSERT (tanpa name). frappe.client.save meng-insert
			// dokumen baru (docstatus 0); fetch_from, snapshot & pricing diisi server saat
			// validate. Setelah tersimpan → buka detailnya.
			delete payload.name
			payload.docstatus = 0
			const saved = await saveDoc(payload)
			notifySuccess(
				isNew.value ? 'Motor Tarikan berhasil dibuat.' : 'Draft amandemen berhasil dibuat.'
			)
			router.replace({ name: 'MotorTarikanDetail', params: { name: saved?.name } })
			return
		}
		payload.name = name.value
		await saveDoc(payload)
		await doc.fetch()
		editMode.value = false
		loadActions()
		notifySuccess('Perubahan berhasil disimpan.')
	} catch (e) {
		saveError.value = e.message || String(e)
		notifyError(e, 'Gagal menyimpan')
	} finally {
		saving.value = false
	}
}

// ---- Aksi submittable: Cancel & Amend (Frappe core) ------------------------
const actionsOpen = ref(false)
const actionState = reactive({ canSubmit: false, canCancel: false, canAmend: false, busy: '' })

// Modal konfirmasi in-app (pengganti window.confirm — WAJIB karena dibungkus APK
// via Capacitor/Codemagic, dialog browser tidak muncul di webview).
const confirmDialog = reactive({
	open: false,
	title: '',
	message: '',
	label: 'Ya',
	variant: 'primary', // 'primary' | 'success' | 'danger'
	onConfirm: null,
})
function askConfirm(opts, onConfirm) {
	confirmDialog.title = opts.title || 'Konfirmasi'
	confirmDialog.message = opts.message || ''
	confirmDialog.label = opts.label || 'Ya'
	confirmDialog.variant = opts.variant || 'primary'
	confirmDialog.onConfirm = onConfirm
	actionsOpen.value = false
	confirmDialog.open = true
}
function confirmYes() {
	const fn = confirmDialog.onConfirm
	confirmDialog.open = false
	confirmDialog.onConfirm = null
	if (typeof fn === 'function') fn()
}
function confirmNo() {
	confirmDialog.open = false
	confirmDialog.onConfirm = null
}
const confirmBtnClass = computed(() => {
	if (confirmDialog.variant === 'danger') return 'bg-red-600 hover:bg-red-700'
	if (confirmDialog.variant === 'success') return 'bg-green-600 hover:bg-green-700'
	return 'bg-primary hover:bg-primary/90'
})
const confirmIconClass = computed(() => {
	if (confirmDialog.variant === 'danger') return 'bg-ui-surface-red-100 text-ui-ink-red-600'
	if (confirmDialog.variant === 'success') return 'bg-ui-surface-green-100 text-ui-ink-green-600'
	return 'bg-primary/10 text-primary'
})

// ---- Date picker in-app (pengganti <input type=date>) ----------------------
// Satu kalender bottom-sheet dipakai bergantian oleh semua field Date (targetnya
// disimpan di datePicker.fieldname). Format nilai 'YYYY-MM-DD' (lokal, tanpa geser
// timezone). Cocok untuk webview APK — tidak bergantung date picker native browser.
const DP_WEEKDAYS = ['Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab', 'Min']
const DP_MONTHS = [
	'Januari',
	'Februari',
	'Maret',
	'April',
	'Mei',
	'Juni',
	'Juli',
	'Agustus',
	'September',
	'Oktober',
	'November',
	'Desember',
]
const datePicker = reactive({
	open: false,
	fieldname: '',
	label: 'Pilih Tanggal',
	cursor: new Date(),
})
function dpYmd(d) {
	const m = String(d.getMonth() + 1).padStart(2, '0')
	const day = String(d.getDate()).padStart(2, '0')
	return `${d.getFullYear()}-${m}-${day}`
}
function dpParse(s) {
	const [y, m, d] = String(s).split('-').map(Number)
	return new Date(y, (m || 1) - 1, d || 1)
}
function openDatePicker(field) {
	if (isFieldReadOnly(field)) return
	datePicker.fieldname = field.fieldname
	datePicker.label = field.label || 'Pilih Tanggal'
	const base = form[field.fieldname] || dpYmd(new Date())
	const d = dpParse(base)
	datePicker.cursor = new Date(d.getFullYear(), d.getMonth(), 1)
	datePicker.open = true
}
const dpLabel = computed(
	() => `${DP_MONTHS[datePicker.cursor.getMonth()]} ${datePicker.cursor.getFullYear()}`
)
const dpDays = computed(() => {
	const year = datePicker.cursor.getFullYear()
	const month = datePicker.cursor.getMonth()
	const first = new Date(year, month, 1)
	const startOffset = (first.getDay() + 6) % 7 // Senin = 0
	const daysInMonth = new Date(year, month + 1, 0).getDate()
	const cells = []
	for (let i = 0; i < startOffset; i++) cells.push(null)
	for (let d = 1; d <= daysInMonth; d++) cells.push(new Date(year, month, d))
	return cells
})
function dpPrevMonth() {
	datePicker.cursor = new Date(
		datePicker.cursor.getFullYear(),
		datePicker.cursor.getMonth() - 1,
		1
	)
}
function dpNextMonth() {
	datePicker.cursor = new Date(
		datePicker.cursor.getFullYear(),
		datePicker.cursor.getMonth() + 1,
		1
	)
}
function dpDayClass(date) {
	const s = dpYmd(date)
	if (s === form[datePicker.fieldname]) return 'rounded-full bg-primary font-semibold text-ui-onPrimary'
	if (s === dpYmd(new Date())) return 'rounded-full font-semibold text-primary'
	return 'rounded-full text-ui-ink-gray-700 hover:bg-ui-surface-gray-100'
}
function pickDate(date) {
	form[datePicker.fieldname] = dpYmd(date)
	datePicker.open = false
}
function clearDate() {
	if (datePicker.fieldname) form[datePicker.fieldname] = ''
	datePicker.open = false
}

async function loadActions() {
	actionState.canSubmit = false
	actionState.canCancel = false
	actionState.canAmend = false
	const ds = doc.data?.docstatus
	let ep = null
	if (ds === 0) ep = 'can_submit'
	else if (ds === 1) ep = 'can_cancel'
	else if (ds === 2) ep = 'can_amend'
	if (!ep) return
	try {
		const params = new URLSearchParams({ name: name.value })
		const res = await fetch(
			`/api/method/juragan.api.portal.motor_tarikan.${ep}?${params.toString()}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		if (res.ok) {
			const ok = !!(await res.json()).message
			if (ds === 0) actionState.canSubmit = ok
			else if (ds === 1) actionState.canCancel = ok
			else actionState.canAmend = ok
		}
	} catch (e) {
		/* abaikan */
	}
}

async function doSubmit() {
	if (actionState.busy) return
	actionState.busy = 'submit'
	saveError.value = ''
	try {
		const res = await fetch('/api/method/juragan.api.portal.motor_tarikan.submit', {
			method: 'POST',
			credentials: 'include',
			headers: {
				'Content-Type': 'application/json',
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: JSON.stringify({ name: name.value }),
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
		actionsOpen.value = false
		await doc.fetch()
		loadActions()
		notifySuccess('Dokumen berhasil di-submit.')
	} catch (e) {
		saveError.value = e.message || String(e)
		actionsOpen.value = false
		notifyError(e, 'Gagal submit')
	} finally {
		actionState.busy = ''
	}
}

async function doCancel() {
	if (actionState.busy) return
	actionState.busy = 'cancel'
	saveError.value = ''
	try {
		const res = await fetch('/api/method/juragan.api.portal.motor_tarikan.cancel', {
			method: 'POST',
			credentials: 'include',
			headers: {
				'Content-Type': 'application/json',
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: JSON.stringify({ name: name.value }),
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
		actionsOpen.value = false
		await doc.fetch()
		loadActions()
		notifySuccess('Dokumen berhasil dibatalkan.')
	} catch (e) {
		saveError.value = e.message || String(e)
		actionsOpen.value = false
		notifyError(e, 'Gagal membatalkan')
	} finally {
		actionState.busy = ''
	}
}

// Klik Amend → buka mode Amend (draft belum tersimpan). Dokumen baru dibuat saat Save.
function doAmend() {
	actionsOpen.value = false
	router.push({ name: 'MotorTarikanAmend', params: { from: name.value } })
}

async function loadAmendDraft() {
	try {
		const params = new URLSearchParams({ name: amendFrom.value })
		const res = await fetch(
			`/api/method/juragan.api.portal.motor_tarikan.prepare_amend?${params.toString()}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
		loadForm(json.message || {})
		editMode.value = true
		amendReady.value = true
	} catch (e) {
		saveError.value = e.message || String(e)
		amendReady.value = true
	}
}

// Form baru (mode New): isi default dari meta (Today → tanggal hari ini), lalu
// samakan status_unit dengan tipe_motor (mirror client script desk).
function todayStr() {
	const d = new Date()
	return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(
		d.getDate()
	).padStart(2, '0')}`
}
function applyTipeDefaults() {
	// status_unit read-only & reqd → di-set otomatis mengikuti tipe (seperti desk).
	if (form.tipe_motor === 'Titipan') {
		form.status_unit = 'Stok Titipan'
	} else {
		form.status_unit = 'Stok Tebus'
		if (!form.status_inspeksi) form.status_inspeksi = 'Belum Inspeksi'
	}
}
function initNewForm() {
	const init = {}
	for (const f of metaFields.value) {
		if (SKIP_TYPES.includes(f.fieldtype)) continue
		let d = f.default
		if (d === undefined || d === null || d === '') continue
		if (d === 'Today') d = todayStr()
		// Default dari meta SELALU string. Untuk Check, "0" adalah string
		// non-kosong yang truthy di JS: tanpa dikonversi, kotaknya tampil
		// tercentang, dan depends_on / mandatory_depends_on yang membacanya
		// ikut menyala (mis. Biaya Pick Up jadi wajib padahal tidak dicentang).
		if (f.fieldtype === 'Check') d = parseInt(d, 10) ? 1 : 0
		else if (isNumberField(f.fieldtype)) d = Number(d) || 0
		init[f.fieldname] = d
	}
	if (!init.tipe_motor) init.tipe_motor = 'Tarikan'
	for (const k of Object.keys(form)) delete form[k]
	Object.assign(form, init)
	applyTipeDefaults()
	editMode.value = true
	amendReady.value = true
}

// tipe_motor berubah di mode entri draft → sesuaikan status_unit default.
watch(
	() => form.tipe_motor,
	() => {
		if (isDraftEntry.value) applyTipeDefaults()
	}
)

// Bottom bar tampil bila: mode entri draft (New/Amend)/edit, atau ada aksi.
const showBottomBar = computed(
	() =>
		isDraftEntry.value ||
		editMode.value ||
		(!!doc.data && (actionState.canSubmit || actionState.canCancel || actionState.canAmend))
)

// ---- Muat meta -------------------------------------------------------------
async function loadMeta() {
	try {
		const res = await fetch(
			`/api/method/frappe.desk.form.load.getdoctype?doctype=${encodeURIComponent(DOCTYPE)}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		if (!res.ok) throw new Error(`HTTP ${res.status}`)
		const json = await res.json()
		const docs = json.docs || json.message?.docs || []
		const dt = docs.find((x) => x.name === DOCTYPE) || docs[0]
		metaFields.value = (dt && dt.fields) || []
		syncFormFromDoc()
		loadLinkMeta().catch(() => {})
	} catch (e) {
		/* meta gagal → section tidak terbentuk */
	}
}

// Inisialisasi konten route saat ini. Dipanggil di mount & saat route berubah —
// komponen dipakai ulang antara detail ⇄ amend (param berubah, instance sama).
async function initPage() {
	editMode.value = false
	amendReady.value = false
	saveError.value = ''
	openDropdown.value = ''
	actionState.canSubmit = false
	actionState.canCancel = false
	actionState.canAmend = false
	if (isNew.value) {
		initNewForm()
	} else if (isAmend.value) {
		await loadAmendDraft()
	} else {
		await doc.fetch()
		loadActions()
	}
}

onMounted(async () => {
	await refreshCsrfToken()
	loadMyRoles()
	await Promise.all([loadMeta(), loadWorkflowEditMap(), loadPermlevelAccess()])
	await initPage()
	await nextTick()
	measureSticky()
	setupStickyObservers()
	window.addEventListener('resize', measureSticky)
})

onBeforeUnmount(() => {
	window.removeEventListener('resize', measureSticky)
	_stickyRO?.disconnect()
	_stickyRO = null
})

watch(
	() => route.fullPath,
	() => initPage()
)
</script>
